function shouldTerminateToolBatch(finalizedCalls) {
	// ODS: in this release write, edit and apply_patch set terminate only for a
	// change that left the file as it was. That is an ordinary result: the
	// model still gets the next turn to answer. Other terminating results end
	// the batch as before.
	return finalizedCalls.length > 0 && finalizedCalls.every((finalized) => finalized.result.terminate === true && ![
		"write",
		"edit",
		"apply_patch"
	].includes(finalized.toolCall?.name));
}
